import{_ as l,a0 as p,w as o,s as d,ao as r,I as n,x as t,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Bash 基礎知識系列 #3：傳遞參數和接受用户輸入 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基礎知識系列 #3：傳遞參數和接受用户輸入 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基礎知識系列 #3：傳遞參數和接受用户輸入 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基礎知識系列 #3：傳遞參數和接受用户輸入 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs","title":"Bash 基礎知識系列 #3：傳遞參數和接受用户輸入","tag":"202307","desc":""},"relativePath":"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs.md","filePath":"[post].md"}'),h={name:"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs.md"};function c(g,s,u,b,k,m){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="bash-基礎知識系列-3-傳遞參數和接受用户輸入" tabindex="-1">Bash 基礎知識系列 #3：傳遞參數和接受用户輸入 <a class="header-anchor" href="#bash-基礎知識系列-3-傳遞參數和接受用户輸入" aria-label="Permalink to “Bash 基礎知識系列 #3：傳遞參數和接受用户輸入”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/15/094330dzt3s3ygshsst39t.jpg" alt=""></p><blockquote><p>在 Bash 基礎系列的這一章中，學習如何向 Bash 腳本傳遞參數並使它們具有交互性。</p></blockquote><p>來讓 Bash 腳本有參數吧 😉</p><p>你可以通過向 Bash 腳本傳遞變量來使其更加有用和更具交互性。</p><p>讓我通過示例詳細向你展示這一點。</p><h3 id="將參數傳遞給-shell-腳本" tabindex="-1">將參數傳遞給 Shell 腳本 <a class="header-anchor" href="#將參數傳遞給-shell-腳本" aria-label="Permalink to “將參數傳遞給 Shell 腳本”">​</a></h3><p>當你運行 Shell 腳本時，你可以按以下方式向其中添加其他變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_script.sh var1 var2</span></span></code></pre></div><p>在腳本內部，你可以使用 <code>$1</code> 作為第一個參數，<code>$2</code> 作為第二個參數，依此類推。</p><blockquote><p>💡 <code>$0</code> 是一個特殊變量，保存正在執行的腳本的名稱。</p></blockquote><p>讓我們通過一個實際的例子來看看。切換到保存練習 Bash 腳本的目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p bash_scripts &amp;&amp; cd bash_scripts</span></span></code></pre></div><p>現在，創建一個名為 <code>arguments.sh</code> （我想不出更好的名稱）的新 Shell 腳本，並向其中添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Script name is: $0&quot;</span></span>
<span class="line"><span>echo &quot;First argument is: $1&quot;</span></span>
<span class="line"><span>echo &quot;Second argument is: $2&quot;</span></span></code></pre></div><p>保存文件並使其可執行。現在像往常一樣運行腳本，但這次向其中添加任意兩個字符串。你將看到屏幕上打印的詳細信息。</p><blockquote><p>🚧 參數由空格（空格、製表符）分隔。如果參數中有空格，請使用（英文）雙引號將其引起來，否則它將被視為單獨的參數。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/06/run-bash-script-with-arguments.png" alt="Pass arguments to the bash scripting"></p><blockquote><p>💡 Bash 腳本最多支持 255 個參數。但對於參數 10 及以上，你必須使用花括號 <code>\${10}</code>、<code>\${11}</code>...<code>\${n}</code>。</p></blockquote><p>正如你所看到的，<code>$0</code> 代表腳本名稱，而其餘參數存儲在編號變量中。你還可以在腳本中使用一些其他特殊變量。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">特殊變量</th><th style="text-align:left;">變量描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>$0</code></td><td style="text-align:left;">腳本名稱</td></tr><tr><td style="text-align:left;"><code>$1</code>、<code>$2</code>、……<code>$9</code></td><td style="text-align:left;">腳本參數</td></tr><tr><td style="text-align:left;"><code>\${n}</code></td><td style="text-align:left;">腳本參數從 10 到 255</td></tr><tr><td style="text-align:left;"><code>$#</code></td><td style="text-align:left;">參數數量</td></tr><tr><td style="text-align:left;"><code>$@</code></td><td style="text-align:left;">所有參數</td></tr><tr><td style="text-align:left;"><code>$$</code></td><td style="text-align:left;">當前 Shell 的進程 ID</td></tr><tr><td style="text-align:left;"><code>$!</code></td><td style="text-align:left;">最後執行的命令的進程 ID</td></tr><tr><td style="text-align:left;"><code>$?</code></td><td style="text-align:left;">最後執行命令的退出狀態</td></tr></tbody></table></div><blockquote><p>🏋️‍♀️ 修改上面的腳本以顯示參數數量。</p></blockquote><h4 id="如果參數數量不匹配怎麼辦" tabindex="-1">如果參數數量不匹配怎麼辦？ <a class="header-anchor" href="#如果參數數量不匹配怎麼辦" aria-label="Permalink to “如果參數數量不匹配怎麼辦？”">​</a></h4><p>在上面的示例中，你為 Bash 腳本提供了兩個參數並在腳本中使用了它們。</p><p>但是，如果你只提供一個參數或三個參數怎麼辦？</p><p>讓我們實際做一下吧。</p><p><img src="https://itsfoss.com/content/images/2023/06/passing-non-matching-arguments-bash-shell.png" alt="Passing fewer or more arguments to bash script"></p><p>正如你在上面所看到的，當你提供的參數超出預期時，結果仍然是一樣的。不使用其他參數，因此不會產生問題。</p><p>但是，當你提供的參數少於預期時，腳本將顯示空白。如果腳本的一部分依賴於缺少的參數，這可能會出現問題。</p><h3 id="接受用户輸入並製作交互式-bash-腳本" tabindex="-1">接受用户輸入並製作交互式 Bash 腳本 <a class="header-anchor" href="#接受用户輸入並製作交互式-bash-腳本" aria-label="Permalink to “接受用户輸入並製作交互式 Bash 腳本”">​</a></h3><p>你還可以創建提示用户通過鍵盤提供輸入的 Bash 腳本。這使你的腳本具有交互性。</p><p><code>read</code> 命令提供了此功能。你可以這樣使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;Enter something&quot;</span></span>
<span class="line"><span>read var</span></span></code></pre></div><p>上面的 <code>echo</code> 命令不是必需的，但最終用户不會知道他們必須提供輸入。然後用户在按回車鍵之前輸入的所有內容都存儲在 <code>var</code> 變量中。</p><p>你還可以顯示提示消息並在單行中獲取值，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>read -p &quot;Enter something? &quot; var</span></span></code></pre></div><p>讓我們看看它的實際效果。創建一個新的 <code>interactive.sh</code> Shell 腳本，內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;What is your name, stranger?&quot;</span></span>
<span class="line"><span>read name</span></span>
<span class="line"><span>read -p &quot;What&#39;s your full name, $name? &quot; full_name</span></span>
<span class="line"><span>echo &quot;Welcome, $full_name&quot;</span></span></code></pre></div><p>在上面的示例中，我使用 <code>name</code> 變量來獲取名稱。然後我在提示中使用 <code>name</code> 變量，並在 <code>full_name</code> 變量中獲取用户輸入。我使用了兩種使用 <code>read</code> 命令的方法。</p><p>現在，如果你授予執行權限，然後運行此腳本，你會注意到該腳本顯示 <code>What is your name, stranger?</code>，然後等待你從鍵盤輸入內容。你提供輸入，然後它會顯示 <code>What&#39;s your full name</code> 消息，並再次等待輸入。</p><p>以下是供你參考的示例輸出：</p><p><img src="https://itsfoss.com/content/images/2023/06/interactive-bash-shell-script.png" alt="Interactive bash shell script"></p><h3 id="🏋️-練習時間" tabindex="-1">🏋️ 練習時間 <a class="header-anchor" href="#🏋️-練習時間" aria-label="Permalink to “🏋️ 練習時間”">​</a></h3><p>是時候練習你所學到的東西了。嘗試為以下場景編寫簡單的 Bash 腳本。</p><p><strong>練習 1</strong>：編寫一個帶有三個參數的腳本。你必須使腳本以相反的順序顯示參數。</p><p>預期輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~/bash_scripts$ ./reverse.sh ubuntu fedora arch</span></span>
<span class="line"><span>Arguments in reverse order:</span></span>
<span class="line"><span>arch fedora ubuntu</span></span></code></pre></div><p><strong>練習 2</strong>：編寫一個腳本，顯示傳遞給它的參數數量。</p><p>提示：使用特殊變量 <code>$#</code>。</p><p>預期輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~/bash_scripts$ ./arguments.sh one and two and three</span></span>
<span class="line"><span>Total number of arguments: 5</span></span></code></pre></div><p><strong>練習 3</strong>：編寫一個腳本，將文件名作為參數並顯示其行號。</p><p>提示：使用 <code>wc</code> 命令來計算行號。</p><p>你可以在社區中討論你的解決方案。</p><p>很好！ 現在你可以（傳遞）參數了 😃 在下一章中，你將學習在 Bash 中執行基本數學運算。</p><p><em>（題圖：MJ/5a75aa2f-1cb1-4009-a4e6-683cf61bc892）</em></p><hr>`,57)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),a(e,{href:"https://itsfoss.com/bash-pass-arguments/"},{default:i(()=>[...s[0]||(s[0]=[t("https://itsfoss.com/bash-pass-arguments/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=t("作者：",-1)),a(e,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...s[2]||(s[2]=[t("Abhishek Prakash",-1)])]),_:1}),s[7]||(s[7]=t(" 選題：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[t("lkxed",-1)])]),_:1}),s[8]||(s[8]=t(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[t("Linux中國",-1)])]),_:1}),s[14]||(s[14]=t(" 榮譽推出",-1))])])}const v=l(h,[["render",c]]);export{x as __pageData,v as default};
